sys_ui_action.client_script_v2:
function onClick(g_form) {
    var errorMessage = 'A mensagem deve conter pelo menos 20 caracteres.';

    g_modal.showFields({
        title: 'Solicitar Informações',
        instruction: 'Informe a mensagem que será enviada ao aluno (mínimo de 20 caracteres).',
        fields: [{
            type: 'textarea',
            name: 'message',
            label: 'Mensagem ao aluno',
            mandatory: true,
            validationCallback: function (value) {
                return String(value || '').trim().length >= 20
                    ? null
                    : errorMessage;
            }
        }],
        size: 'lg'
    }).then(function (result) {
        var field = result.updatedFields.find(function (item) {
            return item.name === 'message';
        });

        var message = String(field ? field.value || '' : '').trim();

        if (message.length < 20) {
            g_form.addErrorMessage(errorMessage);
            return;
        }

        var ga = new GlideAjax('x_fub_fundbrad_ev.EvSolicitarInformacoesAjax');

        ga.addParam('sysparm_name', 'solicitar');
        ga.addParam('sysparm_record_id', g_form.getUniqueValue());
        ga.addParam('sysparm_message', message);

        ga.getXMLAnswer(function (answer) {
            var response;

            try {
                response = JSON.parse(answer || '{}');
            } catch (error) {
                g_form.addErrorMessage('Resposta inválida do servidor.');
                return;
            }

            if (!response.success) {
                g_form.addErrorMessage(
                    response.error || 'Não foi possível solicitar informações.'
                );
                return;
            }

            g_form.addInfoMessage('Informações solicitadas com sucesso.');
            g_form.reload();
        });
    });
}

sys_ui_action.script:
function evSolicitarInformacoes() {
    var dialog = new GlideModal(
        'x_fub_fundbrad_ev_ev_solicitar_informacoes_modal'
    );

    dialog.setTitle('Solicitar Informações');
    dialog.setPreference(
        'sysparm_record_id',
        g_form.getUniqueValue()
    );
    dialog.setWidth(600);
    dialog.render();

    return false;
}
